-- ══════════════════════════════════════════════════════════════
-- PlanB Market 시드 데이터
--
-- 이 파일은 생성기로 뽑은 것임. 원장 balance_after가 그 시점까지의 누적 잔액이라
-- 손으로 쓰면 거의 확실히 틀림. 회원 잔액도 과거 거래를 다 반영한 결과값이다.
--
-- 시각은 전부 CURRENT_TIMESTAMP 기준 상대값이라 언제 띄워도 시나리오가 성립함.
-- 티켓 1번은 2분 뒤 만료 — 스케줄러가 도는 걸 실시간으로 볼 수 있게 넣어둔 것.
-- ══════════════════════════════════════════════════════════════

-- ─── 회원 5명 (잔액은 초기 충전 500,000 + 과거 거래 정산 반영 결과) ───

-- ─── 티켓 (1~20 활성, 21~35 과거 거래분) ───

-- ─── 판매 등록 ───

-- ─── 완료된 과거 거래 15건 (가격 추천 통계의 표본) ───

-- ─── 원장 ───
-- 모든 금전 이동이 DEBIT 1줄 + CREDIT 1줄 쌍으로 들어가 있음.
-- 그래서 SUM(DEBIT) = SUM(CREDIT)이 시드 상태에서 이미 성립함.

-- ─── 식별자 시퀀스 재시작 ───
-- 시드는 id를 직접 박아 넣어서 IDENTITY 카운터가 그대로 1에 머물러 있음.
-- 안 맞춰주면 앱에서 첫 INSERT를 할 때 PK가 겹쳐서 터짐.
ALTER TABLE ticket ALTER COLUMN id RESTART WITH 100;
ALTER TABLE listing ALTER COLUMN id RESTART WITH 100;
ALTER TABLE escrow ALTER COLUMN id RESTART WITH 100;
ALTER TABLE ledger ALTER COLUMN id RESTART WITH 201;
